        return 0;
    float substrateIor = 1 + ((uint(material.normalMatrix[0][1]) >> 8) & 4095u) / 2047.5;
    return float4(factor * map.x, material.normalMatrix[1][3],
                  lerp(material.normalMatrix[2][3], material.normalMatrix[3][3], map.y), substrateIor);
