float4 anisotropicFrame(float2 params, float3 normal, float3 tangent, float3 bitangent)
{
    if (params.x <= 0)
        return 0;
    float3 t = anisotropicTangent(normal, tangent);
    float3 b = cross(normal, t);
    if (dot(b, bitangent) < 0)
        b = -b;
